test('a public task read proves one record with no holder, and refuses unproved or malformed state',async()=>{const f=fixture(),seen=[],read=f.native.publicState;f.native.publicState=async s=>{seen.push(s);return read(s);};const r=await f.service.publicTask('CT-one');assert.equal(r.authority,'native');assert.equal(r.verified,true);assert.equal(r.task.acceptance_digest,sha('Answer is 42'));assert.equal(r.proof.height,'20');assert.deepEqual(seen.map(s=>Object.keys(s)),[['keys']]);assert.deepEqual(seen[0].keys,['central_task/CT-one']);assert.equal(await f.service.publicTask('CT-absent'),null);await reject(f.service.publicTask('../x'),'invalid_central_task');f.records['central_task/CT-one'].criteria='Answer is 43';await reject(f.service.publicTask('CT-one'),'central_proof_unavailable');const g=fixture();g.patchProof({headerTime:new Date(Date.now()-121000).toISOString()});await reject(g.service.publicTask('CT-one'),'central_proof_unavailable');const h=fixture();h.native.configured=false;assert.equal(await h.service.publicTask('CT-one'),null);});
test('open-first listing: newest-first order and an open-only filter never hide open tasks in the middle pages',async()=>{
 const f=fixture(),base=f.records['central_task/CT-one'],open=new Set(['CT-20','CT-35','CT-60']);f.records.central_task_count='60';
 for(let n=2;n<=60;n++){const id='CT-'+n;f.records['central_task_index/'+String(n).padStart(20,'0')]={id,project:'P-one'};f.records['central_task/'+id]={...structuredClone(base),id,...(open.has(id)?{}:{state:'accepted',winner:'CS-w'+n,reserved:'0',paid:'1200000'})};}
 f.records['central_task/CT-one']={...base,state:'under_review',pending:'CS-p'};
 // The default listing is unchanged: oldest first.
 assert.equal((await f.service.tasks(f.user,{cursor:'0',limit:12})).tasks[0].id,'CT-one');
 const newest=await f.service.tasks(f.user,{cursor:'0',limit:3,order:'newest'});assert.deepEqual(newest.tasks.map(t=>t.id),['CT-60','CT-59','CT-58']);assert.equal(newest.nextCursor,'3');assert.equal(newest.total,'60');assert.equal(newest.order,'newest');
 const seen=[];let cursor='0',pages=0,first=null;for(;;){const r=await f.service.tasks(f.user,{cursor,limit:12,order:'newest',state:'open'});first??=r;pages++;assert.ok(BigInt(r.scanned)<=48n);for(const t of r.tasks){assert.equal(t.state,'open');assert.equal(t.pending,'');assert.equal(t.winner,'');seen.push(t.id);}if(!r.more)break;cursor=r.nextCursor;}
 assert.deepEqual(seen,['CT-60','CT-35','CT-20']);assert.equal(pages,2);assert.equal(first.tasks[0].id,'CT-60');assert.equal(first.openCount,undefined);
 // A page that fills `limit` stops right after its last open task, so nothing is skipped.
 const one=await f.service.tasks(f.user,{cursor:'0',limit:1,order:'newest',state:'open'});assert.deepEqual(one.tasks.map(t=>t.id),['CT-60']);assert.equal(one.nextCursor,'1');assert.equal(one.more,true);
 const g=fixture(),all=await g.service.tasks(g.user,{state:'open'});assert.deepEqual(all.tasks.map(t=>t.id),['CT-one']);assert.equal(all.openCount,'1');assert.equal(all.more,false);
 for(const bad of [{order:'oldest'},{state:'closed'},{order:'newest',cursor:'61'}])await assert.rejects(f.service.tasks(f.user,bad),e=>e.status===400||e.statusCode===400||/invalid_central/.test(e.code??''));
});

function withAwards(f,n){const roles=[];let solver=0n,reviewer=0n;for(let i=1;i<=n;i++){const role=i%3===0?'reviewer':'solver',sub='CS-'+i,amount=String(1000000+i);roles.push(role);f.records['central_award_index/'+f.user.address+'/'+String(i).padStart(20,'0')]={role,submission:sub};f.records['central_award/'+role+'/'+sub]={role,submission:sub,member:f.user.address,task:'CT-'+i,project:'P-one',amount,height:'10'};if(role==='solver')solver+=BigInt(amount);else reviewer+=BigInt(amount);}f.records['central_earnings/'+f.user.address]={member:f.user.address,solver:String(solver),reviewer:String(reviewer),total:String(solver+reviewer),awards:String(n)};}
test('award history pages through every award beyond the latest twelve under proof',async()=>{const f=fixture();withAwards(f,30);const status=await f.service.status(f.user);assert.equal(status.awards.length,12);assert.equal(status.awardsScope.complete,false);assert.equal(status.awardsScope.more,'GET /api/native/central/awards?cursor=18');
 const seen=[];let cursor,page;do{page=await f.service.awards(f.user,{...(cursor?{cursor}:{}),limit:12});seen.push(...page.awards);cursor=page.nextCursor;}while(page.more);
 assert.equal(seen.length,30);assert.deepEqual(seen.map(a=>a.submission),Array.from({length:30},(_,i)=>'CS-'+(30-i)));assert.equal(seen[0].position,'30');assert.equal(page.nextCursor,null);assert.equal(page.total,'30');
 const all=await f.service.awards(f.user,{});assert.equal(all.awards.length,30);assert.equal(all.more,false);
 const mid=await f.service.awards(f.user,{cursor:'18',limit:5});assert.deepEqual(mid.awards.map(a=>a.submission),['CS-18','CS-17','CS-16','CS-15','CS-14']);assert.equal(mid.nextCursor,'13');
 for(const body of [{cursor:'31'},{cursor:'01'},{limit:51},{limit:0},{other:1}])await assert.rejects(f.service.awards(f.user,body),e=>['invalid_award_cursor'].includes(e.code),JSON.stringify(body));
 f.records['central_award/solver/CS-4'].member=OTHER;await reject(f.service.awards(f.user,{cursor:'5',limit:5}),'central_proof_unavailable');
 const none=fixture();assert.deepEqual((await none.service.awards(none.user,{})).awards,[]);});
test('task page and detail say whether the task can be taken and why not, without changing native terms',async()=>{
 const f=fixture();let page=await f.service.tasks(f.user,{});assert.equal(page.tasks[0].claimable,true);assert.equal(page.tasks[0].why_not,null);
 let detail=await f.service.task(f.user,'CT-one');assert.equal(detail.claimable,true);assert.equal(detail.next_step,'submit');assert.equal(detail.task.solver_amount,'1000000');
 delete f.records['participation/P-one/'+f.user.address+'/'];detail=await f.service.task(f.user,'CT-one');assert.equal(detail.claimable,true);assert.equal(detail.next_step,'join');
 for(const [patch,why] of [[{state:'under_review',pending:'CS-x'},'under_review'],[{state:'accepted',winner:'CS-x',reserved:'0',paid:'1200000'},'won'],[{state:'open_unfunded',reserved:'0',paid:'200000'},'not_funded']]){const g=fixture();Object.assign(g.records['central_task/CT-one'],patch);const p=await g.service.tasks(g.user,{});assert.equal(p.tasks[0].claimable,false);assert.equal(p.tasks[0].why_not,why);assert.match(p.tasks[0].why_not_text,/\w/);assert.equal((await g.service.task(g.user,'CT-one')).why_not,why);}
 const h=fixture();h.member.licence='pending';assert.equal((await h.service.task(h.user,'CT-one')).why_not,'licence_inactive');
 const held=createCentralEarningService({store:f.store,native:f.native,enabled:true,taskAvailability:{forTask:()=>({authority:'uain-operator',available:false,reason:'task_specification_unusable'})}});assert.equal((await held.tasks(anotherPublicHolder(),{})).tasks[0].why_not,'on_hold');});

test('award history for a holder that never enrolled answers no awards instead of a proof failure',async()=>{const f=fixture();f.member.absent=true;f.records['member/'+f.user.address]=null;
 const r=await f.service.awards(f.user,{});assert.equal(r.enrolled,false);assert.deepEqual(r.awards,[]);assert.equal(r.total,'0');assert.match(r.note,/Enrol/);
 f.records['member/'+f.user.address]={id:f.user.address,licence:'active'};await reject(f.service.awards(f.user,{}),'central_proof_unavailable');
 // status for a holder proved absent answers "not enrolled" (13 November 2026), and never for a present member.
 const n=fixture();n.member.absent=true;n.records['member/'+n.user.address]=null;const s=await n.service.status(n.user);assert.equal(s.enrolled,false);assert.equal(s.licence,null);assert.equal(s.verified,true);assert.deepEqual(s.awards,[]);assert.match(s.note,/Enrol/);
 n.records['member/'+n.user.address]={id:n.user.address,licence:'active'};await reject(n.service.status(n.user),'central_proof_unavailable');});
// S6 submit path (10 November 2026): before this, submit treated every non-submit operation as a
// project join and a revision as a fresh submission, so a prepared revise, reassess or expire was
// refused at send. Each must now send exactly once while its window rules hold.
function evidenceFixture({deadline='30',height='20'}={}){const f=fixture();f.state.height=height;f.records.central_evidence_activation={policy:'central-evidence-window-v1',window_blocks:'10',height:'10',approved_by:OTHER,evidence_digest:E};Object.assign(f.records['central_task/CT-one'],{state:'under_review',pending:'CS-asked'});f.records['central_submission/CS-asked']={id:'CS-asked',task:'CT-one',author:f.user.address,state:'under_review',height:'15',evidence:'41',evidence_digest:sha('41'),evidence_request_height:'18',evidence_deadline:deadline};return f;}
const revision={operation:'central_submit',payload:{id:'CS-revised',task:'CT-one',evidence:'42',evidence_digest:sha('42'),revises:'CS-asked'}};
test('S6 revision, reassessment and expiry pass submit once and keep the window rules',async()=>{
 for(const body of [revision,{operation:'central_reassess',payload:{submission:'CS-asked'}}]){const f=evidenceFixture(),{intent}=await f.service.prepare(f.user,body);const sent=await f.service.submit(f.user,intent.id,f.signed(intent));assert.equal(sent.attempted,true,body.operation);assert.equal(sent.intent.status,'accepted');assert.equal(f.sends,1);}
 const e=evidenceFixture({deadline:'19'}),expire={operation:'central_evidence_expire',payload:{submission:'CS-asked'}},{intent}=await e.service.prepare(e.user,expire);assert.equal((await e.service.submit(e.user,intent.id,e.signed(intent))).attempted,true);assert.equal(e.sends,1);
 // Window closed between prepare and submit: nothing is sent.
 const late=evidenceFixture(),{intent:lateIntent}=await late.service.prepare(late.user,revision);late.state.height='25';late.records['central_submission/CS-asked'].evidence_deadline='24';await reject(late.service.submit(late.user,lateIntent.id,late.signed(lateIntent)),'central_evidence_action_unavailable');assert.equal(late.sends,0);
 // The revision id was taken meanwhile; reassessment already recorded; activation absent.
 const taken=evidenceFixture(),{intent:t}=await taken.service.prepare(taken.user,revision);taken.records['central_submission/CS-revised']={id:'CS-revised'};await reject(taken.service.submit(taken.user,t.id,taken.signed(t)),'central_submission_exists');
 const twice=evidenceFixture(),{intent:r}=await twice.service.prepare(twice.user,{operation:'central_reassess',payload:{submission:'CS-asked'}});twice.records['central_submission/CS-asked'].reassess=true;await reject(twice.service.submit(twice.user,r.id,twice.signed(r)),'central_evidence_action_unavailable');
 const off=evidenceFixture(),{intent:o}=await off.service.prepare(off.user,revision);off.records.central_evidence_activation=null;await reject(off.service.submit(off.user,o.id,off.signed(o)),'central_evidence_window_inactive');
 for(const f of [taken,twice,off])assert.equal(f.sends,0);
 // A request recorded before activation carries no deadline and stays refused.
 const old=evidenceFixture();delete old.records['central_submission/CS-asked'].evidence_deadline;await reject(old.service.prepare(old.user,revision),'central_evidence_request_absent');
});
